import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { ALL_TOOL_CONTRACTS, saveAgentLabels, saveExperiment, saveExperimentGroup, saveTemplate, toolConfig, } from "bitfab-lib/mcp-contract";
import { readActivePreviewSession } from "./activePreviewSession.js";
import { pushAgentSessionEvent } from "./agentSessionChannel.js";
import { writeAgentRunId } from "./chatSessions/arming.js";
import { McpProxy } from "./mcpProxy.js";
import { resolveCodingAgentDisplayName } from "./resolveCodingAgentDisplayName.js";
export function createMcpServer(platform, getConfig, pluginVersion) {
    const proxy = new McpProxy(platform, pluginVersion);
    function proxyToolCall(toolName, args) {
        const agentRunId = process.env.BITFAB_AGENT_RUN_ID;
        const hasAgentRunId = typeof agentRunId === "string" && agentRunId.trim() !== "";
        if (toolName === "save_trace_plan" && !args.planId && hasAgentRunId) {
            const agentSessionId = process.env.CLAUDE_CODE_SESSION_ID;
            if (agentSessionId) {
                writeAgentRunId(agentSessionId, agentRunId);
            }
        }
        const nextArgs = toolName === "save_trace_plan" && !args.planId && hasAgentRunId
            ? { ...args, source: args.source ?? "analyze_repo", agentRunId }
            : args;
        return proxy.toolCall(getConfig(), toolName, nextArgs);
    }
    // Push an event to the active preview session, if one is open. Returns
    // a promise the caller can await to guarantee ordering (e.g. so an
    // editStarted lands on the bus before the work that follows kicks off).
    // Failures are swallowed: the agent event channel is non-critical and
    // the user already has the SSE `template:updated` re-render path as the
    // real success signal.
    async function pushToActivePreview(event) {
        const active = readActivePreviewSession();
        if (!active) {
            return;
        }
        const config = getConfig();
        if (!config.apiKey) {
            return;
        }
        try {
            await pushAgentSessionEvent({
                serviceUrl: active.serviceUrl,
                apiKey: config.apiKey,
                sessionId: active.sessionId,
            }, event);
        }
        catch {
            // Non-critical: agent-event channel may not be reachable; the
            // `template:updated` SSE path is the real success signal.
        }
    }
    const server = new McpServer({
        name: "Bitfab",
        version: pluginVersion,
    });
    // Every tool but the three below is a straight proxy to the HTTP MCP server:
    // the contract validates the args, and this layer forwards them untouched.
    const SPECIAL_TOOL_NAMES = new Set([
        saveAgentLabels.name,
        saveExperiment.name,
        saveExperimentGroup.name,
        saveTemplate.name,
    ]);
    for (const contract of ALL_TOOL_CONTRACTS) {
        if (SPECIAL_TOOL_NAMES.has(contract.name)) {
            continue;
        }
        server.registerTool(contract.name, toolConfig(contract), async (args) => proxyToolCall(contract.name, args));
    }
    server.registerTool(saveAgentLabels.name, toolConfig(saveAgentLabels), async ({ testRunId, labels }) => proxyToolCall("save_agent_labels", {
        testRunId,
        // Mirror originalTraceId onto the deprecated sourceTraceId alias:
        // servers that predate the rename strip the unknown canonical key and
        // would otherwise see a label with no id; current servers prefer the
        // canonical key and ignore the alias.
        labels: labels.map((l) => l.originalTraceId !== undefined && l.sourceTraceId === undefined
            ? { ...l, sourceTraceId: l.originalTraceId }
            : l),
    }));
    server.registerTool(saveExperiment.name, toolConfig(saveExperiment), async ({ testRunId, name, notes, experimentGroupId }) => {
        if (name === undefined &&
            notes === undefined &&
            experimentGroupId === undefined) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error saving experiment: provide name, notes, and/or experimentGroupId.",
                    },
                ],
                isError: true,
            };
        }
        return proxyToolCall("save_experiment", {
            testRunId,
            name,
            notes,
            experimentGroupId,
        });
    });
    server.registerTool(saveExperimentGroup.name, toolConfig(saveExperimentGroup), async ({ experimentGroupId, testRunIds, name, notes }) => {
        if (experimentGroupId === undefined && testRunIds === undefined) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error saving experiment group: testRunIds is required when creating an experiment group.",
                    },
                ],
                isError: true,
            };
        }
        if (experimentGroupId !== undefined && testRunIds !== undefined) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error saving experiment group: testRunIds cannot be provided when editing an experiment group; editing does not change membership.",
                    },
                ],
                isError: true,
            };
        }
        if (experimentGroupId !== undefined &&
            name === undefined &&
            notes === undefined) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error saving experiment group: provide name and/or notes when editing an experiment group.",
                    },
                ],
                isError: true,
            };
        }
        return proxyToolCall("save_experiment_group", {
            experimentGroupId,
            testRunIds,
            name,
            notes,
        });
    });
    server.registerTool(saveTemplate.name, toolConfig(saveTemplate), async ({ spanType, traceFunctionKey, template, name, description }) => {
        // Await the editStarted push so the banner / card animation hit the
        // browser BEFORE the save completes. Without this, a fast DB write
        // can finish before the SSE delivery, and the editEnded event lands
        // on the bus before editStarted - the user sees the "Saved" flash
        // with no preceding "editing" state.
        await pushToActivePreview({
            type: "editStarted",
            data: {
                spanType,
                traceFunctionKey: traceFunctionKey ?? null,
                agentLabel: resolveCodingAgentDisplayName(),
            },
        });
        try {
            const result = await proxyToolCall("save_template", {
                spanType,
                traceFunctionKey,
                template,
                name,
                description,
            });
            await pushToActivePreview({
                type: "editEnded",
                data: {
                    spanType,
                    traceFunctionKey: traceFunctionKey ?? null,
                    success: true,
                    summary: traceFunctionKey
                        ? `Updated ${spanType} template for ${traceFunctionKey}`
                        : `Updated org-global ${spanType} template`,
                },
            });
            return result;
        }
        catch (err) {
            await pushToActivePreview({
                type: "editEnded",
                data: {
                    spanType,
                    traceFunctionKey: traceFunctionKey ?? null,
                    success: false,
                    summary: err.message ?? "save_template failed",
                },
            });
            throw err;
        }
    });
    return { server, proxy };
}
export async function startMcpServer(platform, getConfig, pluginVersion) {
    const { server } = createMcpServer(platform, getConfig, pluginVersion);
    const transport = new StdioServerTransport();
    await server.connect(transport);
}
